function _rvFmt(r){ r=+r; return (Math.round(r*100)%10===0)?r.toFixed(1):r.toFixed(2); }
const RV_FEED=[
  {ent:'Gopher Request',plat:'Apple App Store',r:5,date:'Jun 12, 2026',title:'Saved my evening',body:'Needed cold medicine at 11pm and a gopher had it at my door in 25 minutes. Unreal.',by:'mealsonwheels22'},
  {ent:'Gopher Request',plat:'Google Play',r:2,date:'Jun 10, 2026',title:'Order kept expiring',body:'Nobody accepted my request for an hour and it just cancelled. Happens too often outside the city.',by:'D. Pittman'},
  {ent:'Gopher Go',plat:'Google Play',r:4,date:'Jun 9, 2026',title:'Good side income',body:'Decent pay if you stick to busy areas. Wish I didn’t have to pay to cash out instantly though.',by:'RaleighRunner'},
  {ent:'Gopher, Inc',plat:'Facebook',r:5,date:'Jun 8, 2026',title:'Great local service',body:'Love supporting a NC company and the support team actually answered me.',by:'Tonya M.'},
  {ent:'Gopher Go',plat:'Apple App Store',r:2,date:'Jun 6, 2026',title:'Verification took forever',body:'Waited days to get approved before I could take a single job.',by:'jaylenc'},
  {ent:'Gopher, Inc',plat:'Nextdoor',r:5,date:'Jun 4, 2026',title:'Neighborhood favorite',body:'Half my street uses it for pharmacy runs now.',by:'Verified Neighbor'},
];
function rvStars(r){const f=Math.round(r);return `<span class="rv-stars">${'★'.repeat(f)}${'☆'.repeat(5-f)}</span>`;}
