function rvBadge(p){return p.logo&&RV_LOGOS[p.logo]?`<span class="rv-logo rv-logo-img">${RV_LOGOS[p.logo]}</span>`:`<span class="rv-logo" style="background:${p.color}">${p.short||''}</span>`;}
function rvName(p){return p.url?`<a href="${p.url}" target="_blank" rel="noopener" class="rv-link">${p.p}</a>`:p.p;}
