/* ===== Cancellation Alerts — learning mechanics (mirrors Message Alerts) ===== */
function cxLoad(){try{return JSON.parse(localStorage.getItem('gopher_cancel')||'{}');}catch(e){return{};}}
function cxSave(s){try{localStorage.setItem('gopher_cancel',JSON.stringify(s));}catch(e){}}
const CX_LBL={fee:'Unapproved \u00b7 fee',nofee:'Unapproved \u00b7 no fee',excused:'Excused',ignore:'Ignore'};
const CX_COL={fee:'#d4503a',nofee:'#d99036',excused:'#0a8f4f',ignore:'#7a8794'};
function _cxAmtBand(a){a=+a||0;return a<25?'<$25':(a<75?'$25-75':'$75+');}
function _cxStage(o){return o&&o.pickedUp?'picked-up':(o&&o.inProg?'in-progress':'accepted');}
function cxFeatures(o){var f=[];if(!o)return f;
  if(o.cat)f.push('cat:'+o.cat);
  if(o.state&&o.state!=='\u2014')f.push('state:'+o.state);
  if(o.dma)f.push('dma:'+o.dma);
  f.push('amount:'+_cxAmtBand(o.total));
  f.push('stage:'+_cxStage(o));
  var _om=(typeof omGet==='function'&&o.id)?omGet(o.id):{};
  var rs=((o._reason||(_om&&_om.cancelReason)||'')+' '+(o._notes||(_om&&_om.notes)||'')).toLowerCase(); // reason + temp notes both feed learning
  var by=o._cancelledBy||(_om&&_om.cancelledBy)||'';
  if(by)f.push('cancelledby:'+(''+by).toLowerCase());
  if(rs){(rs.match(/[a-z]{4,}/g)||[]).forEach(function(w){ if(!/order|cancel|gopher|please|thank|there|would|could|will/.test(w)&&f.length<14) f.push('reason:'+w); });}
  return f;}
function cxCalib(){
  var a=(cxLoad().actions)||{}, byDisp={fee:{},nofee:{},excused:{}}, n={fee:0,nofee:0,excused:0};
  Object.keys(a).forEach(function(id){var ac=a[id];if(!ac||n[ac.action]==null)return;n[ac.action]++;(ac.features||[]).forEach(function(ft){byDisp[ac.action][ft]=(byDisp[ac.action][ft]||0)+1;});});
  return {n:n,byDisp:byDisp,decided:n.fee+n.nofee+n.excused};
}
function _cxTop(map,k){return Object.keys(map).sort(function(x,y){return map[y]-map[x];}).slice(0,k);}
// iQ recommendation — pulsing colored shadow behind the suggested disposition button.
// Predicts from DISCRIMINATING features only (reason:/cancelledby:); category/market/amount/stage proved
// non-predictive. SELF-GATING by confidence: returns null until iQ is sure, so the shadow "turns on" per
// order as calibration grows. Tune the three CX_RECO_* constants to make it more/less eager.
var CX_RECO_MINCONF=0.66, CX_RECO_MINFEATS=2, CX_RECO_MINSUP=3;
function cxRecommend(o){
  if(!o||typeof cxCalib!=='function')return null;
  var cal=cxCalib(); if(cal.decided<8)return null;                 // need a base of decisions first
  var feats=cxFeatures(o).filter(function(f){return /^(reason|cancelledby):/.test(f);});
  if(feats.length<CX_RECO_MINFEATS)return null;
  var score={fee:0,nofee:0,excused:0}, used=0, totsup=0;
  feats.forEach(function(ft){
    var sup=(cal.byDisp.fee[ft]||0)+(cal.byDisp.nofee[ft]||0)+(cal.byDisp.excused[ft]||0);
    if(!sup)return; used++; totsup+=sup;
    ['fee','nofee','excused'].forEach(function(d){ score[d]+=(cal.byDisp[d][ft]||0)/sup; });
  });
  if(used<CX_RECO_MINFEATS||totsup<CX_RECO_MINSUP)return null;
  var top=['fee','nofee','excused'].sort(function(x,y){return score[y]-score[x];})[0];
  var conf=score[top]/used;                                        // avg fraction of matching evidence at the top disposition
  return conf>=CX_RECO_MINCONF?{action:top,conf:conf}:null;
}
function _cxRecoStyle(){ if(typeof document==='undefined'||document.getElementById('cx-reco-style'))return; var s=document.createElement('style'); s.id='cx-reco-style'; s.textContent='@keyframes cxpulse{0%,100%{box-shadow:0 0 3px 1px var(--cxc)}50%{box-shadow:0 0 13px 5px var(--cxc)}}.cx-reco{animation:cxpulse 1.3s ease-in-out infinite}'; (document.head||document.body).appendChild(s); }
function cxAction(id,act,feats){var s=cxLoad();s.actions=s.actions||{};if(s.actions[id]&&s.actions[id].action===act)delete s.actions[id];else s.actions[id]={action:act,ts:new Date().toISOString(),features:feats||[]};cxSave(s);return s.actions[id];}
function _cxFeeConfirm(o){
  return new Promise(function(resolve){
    var gname=(o.gopher||(o.gopherId?'Gopher #'+o.gopherId:'the gopher'));
    var ov=document.createElement('div');
    ov.style.cssText='position:fixed;inset:0;background:rgba(15,20,26,.55);z-index:99999;display:flex;align-items:center;justify-content:center;padding:20px';
    ov.innerHTML='<div style="background:var(--card,#fff);border-radius:16px;max-width:450px;width:100%;padding:22px 24px;box-shadow:0 20px 60px rgba(0,0,0,.3)">'+
      '<div style="font-weight:800;font-size:16px;margin-bottom:8px;color:#b3261e">Assess $5 cancellation fee?</div>'+
      '<div style="font-size:13.5px;line-height:1.55">You\u2019re about to record an <b>Unapproved \u00b7 fee</b> against <b>'+iaEsc(gname)+'</b> for order <b>#'+iaEsc(''+o.id)+'</b>.'+
      '<div style="margin-top:10px;padding:10px 12px;background:#fff6f4;border:1px solid #f3c9c1;border-radius:9px;font-size:12.5px">When the live admin connection is on, this <b>moves money</b>: it records a <b>flat $5</b> cancellation fee as a <b>\u2212$5 negative balance</b> on '+iaEsc(gname)+'\u2019s Stripe Connect account \u2014 <b>withheld from their next payout</b>, not an instant charge \u2014 and logs a strike. Per policy (G40-81) the fee applies only after <b>\u22652 prior no-fee strikes</b>, and a running Stripe balance of <b>\u2212$10</b> auto-deactivates the account. Eligibility and these thresholds are enforced server-side.</div></div>'+
      '<div style="display:flex;gap:10px;justify-content:flex-end;margin-top:18px">'+
        '<button id="cxfc-cancel" class="gb-btn">Cancel</button>'+
        '<button id="cxfc-ok" class="gb-btn" style="background:#b3261e;color:#fff;border-color:#b3261e">Assess $5 fee</button></div></div>';
    document.body.appendChild(ov);
    function done(v){ if(ov.parentNode)ov.parentNode.removeChild(ov); document.removeEventListener('keydown',onkey); resolve(v); }
    function onkey(e){ if(e.key==='Escape')done(false); }
    ov.querySelector('#cxfc-cancel').onclick=function(){done(false);};
    ov.querySelector('#cxfc-ok').onclick=function(){done(true);};
    ov.addEventListener('click',function(e){ if(e.target===ov)done(false); });
    document.addEventListener('keydown',onkey);
  });
}

VIEWS.cancellations=function(){
  var v=el('div');
  var cancelled=(typeof ORD!=='undefined'?ORD:[]).filter(function(o){return o.status==='cancelled';});
  var afterAccept=cancelled.filter(function(o){return (o.gopherId>0||o.gopher)&&(o.inProg||o.pickedUp);});
  var totalOrders=(typeof ORD!=='undefined'&&ORD.length)||1;

  var kwrap=el('div'); v.appendChild(kwrap);
  function kpis(){ var cal=cxCalib(); kwrap.innerHTML='';
    var k=el('div','row kpis');
    k.appendChild(kpi('Cancellations',num(cancelled.length),'orders with status cancelled',{dot:C.red}));
    k.appendChild(kpi('Gopher cancelled after accepting',num(afterAccept.length),'candidate unapproved cancels',{dot:C.amber}));
    k.appendChild(kpi('Classified',num(cal.decided),cal.n.fee+' fee \u00b7 '+cal.n.nofee+' no-fee \u00b7 '+cal.n.excused+' excused',{dot:C.green}));
    k.appendChild(kpi('Share of all orders',(cancelled.length/totalOrders*100).toFixed(1)+'%','of '+num(totalOrders)+' orders',{dot:C.blue}));
    kwrap.appendChild(k);
  }

  var learn=el('div','card');
  learn.innerHTML='<div class="card-h" style="flex-wrap:wrap;gap:8px"><div><h3>Cancellation learning</h3><div class="sub">Classify each cancel; iQ learns the patterns behind fee / no-fee / excused. Export and share for calibration.</div></div>'+
    '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-left:auto">'+
      '<label class="gb-btn" style="cursor:pointer" title="Load a cancel_learnings.json"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 4v12m0-12-4 4m4-4 4 4M5 20h14"/></svg>Import<input id="cx-import" type="file" accept="application/json" style="display:none"></label>'+
      '<button class="gb-btn" id="cx-export"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 16V4m0 12 4-4m-4 4-4-4M5 20h14"/></svg>Export learnings (.json)</button>'+
      '<button class="gb-btn" id="cx-save"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 16V4m0 12 4-4m-4 4-4-4M5 20h14"/></svg>Save full file</button>'+
    '</div></div>'+
    '<div id="cx-learnbar"></div>'+
    '<div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:10px">'+
      '<input id="cx-q" placeholder="Search order #, gopher, requester\u2026" style="flex:1;min-width:200px;border:1px solid var(--line);border-radius:9px;padding:8px 11px;font:inherit;font-size:13px">'+
      '<select id="cx-status" style="border:1px solid var(--line);border-radius:9px;padding:8px 11px;font:inherit;font-size:13px"><option value="open">Unclassified</option><option value="all">All</option><option value="fee">Unapproved \u00b7 fee</option><option value="nofee">Unapproved \u00b7 no fee</option><option value="excused">Excused</option><option value="ignore">Ignored</option></select>'+
      '<select id="cx-sort" style="border:1px solid var(--line);border-radius:9px;padding:8px 11px;font:inherit;font-size:13px"><option value="new">Newest first</option><option value="old">Oldest first</option><option value="amt">Highest amount</option></select>'+
    '</div>';
  v.appendChild(learn);

  var ready=_hqReady();
  var src=el('div','card');
  src.innerHTML='<div class="card-h"><div><h3>Where this connects</h3><div class="sub">The same source the admin panel order page uses.</div></div></div>'+
    '<div class="note">'+(ready
      ? 'Connected. Reason and the order log load live from <b>GET /admin/order/get_details</b> (<code>cancellation_reason</code> + <code>order_logs</code>, where <code>order_status = order_canceled_by_gopher</code>). \u201cUnapproved \u00b7 fee\u201d posts to <b>GET /admin/order_declines/access_gopher_cancelation_fee/{order_id}</b>.'
      : _opEarmark('At integration this reads the live admin API \u2014 reason + order log from GET /admin/order/get_details, fee via access_gopher_cancelation_fee/{order_id}. Until window.MSG_CONFIG is connected, the queue is flagged from order timestamps; your classifications persist locally and export as cancel_learnings.json.'))+
    '</div>';
  v.appendChild(src);

  var card=el('div','card');
  card.innerHTML='<div class="card-h"><div><h3>Cancellation queue</h3><div class="sub" id="cx-sub"></div></div></div><div id="cx-list"></div>';
  v.appendChild(card);
  var list=card.querySelector('#cx-list');
  var dbtn='display:inline-block;font-size:11px;font-weight:600;padding:4px 8px;border:1px solid var(--line,#e6eaee);border-radius:7px;background:var(--card,#fff);color:inherit;cursor:pointer;margin:2px 4px 2px 0';

  function learnbar(){
    var lb=learn.querySelector('#cx-learnbar'); var cal=cxCalib();
    if(!cal.decided){ lb.innerHTML='<div class="ia-learnbar" style="color:var(--muted)"><b>iQ is ready to learn.</b> Classify cancellations as Unapproved \u00b7 fee / no fee / Excused \u2014 iQ builds patterns from category, market, amount, and how far the order got (plus the reason text once live). Then Export learnings (.json) and share it for calibration.</div>'; return; }
    function seg(d){var t=_cxTop(cal.byDisp[d],3).map(function(f){return f.replace(/^[a-z]+:/,'');}); return t.length?(CX_LBL[d].toLowerCase()+' on: '+t.map(iaEsc).join(', ')):''; }
    var parts=['fee','excused','nofee'].map(seg).filter(Boolean);
    lb.innerHTML='<div class="ia-learnbar"><span class="gb-pulse" style="width:7px;height:7px"></span><b>iQ has learned from '+cal.decided+' cancellation decision'+(cal.decided>1?'s':'')+'</b> \u2014 '+cal.n.fee+' unapproved-fee, '+cal.n.nofee+' no-fee, '+cal.n.excused+' excused.'+(parts.length?' Leaning '+parts.join('; ')+'.':'')+' <span style="color:var(--muted)">Export &amp; share for calibration.</span></div>';
  }

  function cxReasonLog(s){
    var oid=s.dataset.oid, tr=s.closest('tr');
    var ex=tr.nextElementSibling; if(ex&&ex.className==='cx-detail'){ ex.parentNode.removeChild(ex); return; }
    var dr=document.createElement('tr'); dr.className='cx-detail';
    var td=document.createElement('td'); td.colSpan=8; td.style.cssText='background:var(--soft,#f7f9fb);font-size:12px;padding:10px 12px';
    td.innerHTML='Loading\u2026'; dr.appendChild(td); tr.parentNode.insertBefore(dr,tr.nextSibling);
    if(!_hqReady()){ td.innerHTML=_opEarmark('Reason and order log load from GET /admin/order/get_details once window.MSG_CONFIG is connected \u2014 the cancellation_reason (e.g. \u201cGot a flat tire\u201d) and the order_logs timeline. Once live, reason keywords also feed the learning.'); return; }
    _hqReq('GET','/admin/order/get_details?id='+oid).then(function(r){
      var o0=(r&&r.data&&(r.data[0]||r.data))||r||{}; var reason=o0.cancellation_reason||'\u2014'; var logs=o0.order_logs||[];
      var o=(typeof ordById==='function'?ordById(+oid):null); if(o)o._reason=reason;
      var lh=logs.map(function(l){return '<div style="display:flex;gap:10px;margin:2px 0"><span style="color:var(--muted);min-width:150px">'+iaEsc(''+(l.created_at||''))+'</span><span>'+iaEsc(''+(l.notes||l.order_status||''))+'</span></div>';}).join('');
      td.innerHTML='<b>Cancellation reason:</b> '+iaEsc(''+reason)+'<div style="margin-top:8px"><b>Order log</b>'+(lh||'<div style="color:var(--muted)">no log rows</div>')+'</div>';
    }).catch(function(e){ td.innerHTML='<span style="color:var(--red)">Could not load ('+iaEsc(''+(e&&e.message||e))+').</span>'; });
  }

  function paint(){
    kpis(); learnbar();
    var a=(cxLoad().actions)||{};
    var q=(learn.querySelector('#cx-q').value||'').toLowerCase().trim();
    var status=learn.querySelector('#cx-status').value, sort=learn.querySelector('#cx-sort').value;
    if(!afterAccept.length){ card.querySelector('#cx-sub').textContent=''; list.innerHTML='<div class="note">No gopher-cancelled-after-accept orders in the current snapshot.</div>'; return; }
    var rows=afterAccept.filter(function(o){
      var ac=a[o.id];
      if(status==='open'&&ac)return false;
      if(status!=='open'&&status!=='all'&&(!ac||ac.action!==status))return false;
      if(q){var hay=('#'+o.id+' '+(o.gopher||'')+' '+(o.req||'')).toLowerCase();if(hay.indexOf(q)<0)return false;}
      return true;
    });
    if(sort==='new')rows.sort(function(a,b){return b.day-a.day;});
    else if(sort==='old')rows.sort(function(a,b){return a.day-b.day;});
    else rows.sort(function(a,b){return (b.total||0)-(a.total||0);});
    var show=rows.slice(0,150); _cxRecoStyle();
    card.querySelector('#cx-sub').textContent=num(rows.length)+' match'+(rows.length>150?' \u00b7 showing first 150':'')+' \u00b7 '+num(afterAccept.length)+' after-accept total';
    var h='<div style="overflow:auto"><table style="font-size:12.5px;width:100%"><thead><tr><th>Order</th><th>Date</th><th>Category</th><th>Market</th><th>Gopher</th><th style="text-align:right">Amount</th><th>Reason &amp; log</th><th>Disposition</th></tr></thead><tbody>';
    show.forEach(function(o){
      var ac=a[o.id]; var stage=_cxStage(o); var reco=(!ac)?cxRecommend(o):null;
      h+='<tr data-oid="'+o.id+'">'+
        '<td><a class="dd-link" data-dd="order" data-id="'+o.id+'" style="color:var(--blue);cursor:pointer">#'+o.id+'</a></td>'+
        '<td>'+dayToStr(o.day)+'</td>'+
        '<td>'+(o.cat||'\u2014')+'</td>'+
        '<td>'+(o.dma?iaEsc(o.dma):(o.state||'\u2014'))+'</td>'+
        '<td>'+(o.gopher?iaEsc(o.gopher):(o.gopherId?'#'+o.gopherId:'\u2014'))+'<div style="font-size:10.5px;color:var(--muted)">'+stage+'</div></td>'+
        '<td style="text-align:right">'+money(o.total||0)+'</td>'+
        '<td><span class="cx-rl" data-oid="'+o.id+'" style="color:var(--blue);cursor:pointer;font-size:11.5px">view</span></td>'+
        '<td><div class="cx-disp" data-oid="'+o.id+'">'+
          ['fee','nofee','excused','ignore'].map(function(d){var on=ac&&ac.action===d;var isreco=(reco&&reco.action===d);var sep=(d==='ignore'?';margin-left:10px':'');var st=dbtn+sep+(on?';background:'+CX_COL[d]+';color:#fff;border-color:'+CX_COL[d]:'')+(isreco?';--cxc:'+CX_COL[d]:'');var ttl=(d==='ignore'?'Dismiss \u2014 excluded from learning':(isreco?'Gopher iQ suggests this ('+Math.round(reco.conf*100)+'% of matching cases)':CX_LBL[d]));return '<button class="cx-btn'+(isreco?' cx-reco':'')+'" data-d="'+d+'" style="'+st+'" title="'+ttl+'">'+CX_LBL[d]+'</button>';}).join('')+
        '</div></td>'+
      '</tr>';
    });
    h+='</tbody></table></div>';
    list.innerHTML=h;
    list.querySelectorAll('.dd-link').forEach(function(b){b.onclick=function(){openOrderDetail(b.dataset.id);};});
    list.querySelectorAll('.cx-rl').forEach(function(s){ s.onclick=function(){ cxReasonLog(s); }; });
    list.querySelectorAll('.cx-disp').forEach(function(box){
      var oid=+box.dataset.oid, o=(typeof ordById==='function'?ordById(oid):null);
      box.querySelectorAll('.cx-btn').forEach(function(btn){
        btn.onclick=async function(){
          var d=btn.dataset.d;
          if(d==='fee'){
            var cur=cxLoad(); var already=cur.actions&&cur.actions[oid]&&cur.actions[oid].action==='fee';
            if(!already){ var ok=await _cxFeeConfirm(o||{id:oid}); if(!ok)return; }
          }
          var feats=(d==='ignore')?[]:cxFeatures(o||{id:oid});
          var res=cxAction(oid,d,feats);
          if(d==='fee'&&res&&_hqReady()){ try{ await _hqReq('GET','/admin/order_declines/access_gopher_cancelation_fee/'+oid); }catch(e){} }
          toast(res?(d==='ignore'?'Ignored \u2014 excluded from learning':'Recorded: '+CX_LBL[d]):'Cleared');
          paint();
        };
      });
    });
  }

  setTimeout(function(){
    if(!list.isConnected)return;
    learn.querySelector('#cx-q').oninput=paint;
    learn.querySelector('#cx-status').onchange=paint;
    learn.querySelector('#cx-sort').onchange=paint;
    learn.querySelector('#cx-save').onclick=function(){ if(typeof exportDashboardFile==='function')exportDashboardFile('Cancellation calibration saved into the file.'); else toast('Save not available'); };
    learn.querySelector('#cx-export').onclick=function(){
      var actions=(cxLoad().actions)||{};
      var blob=new Blob([JSON.stringify({actions:actions},null,2)],{type:'application/json'});
      var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='cancel_learnings.json';a.click();setTimeout(function(){URL.revokeObjectURL(a.href);},1500);
      toast('Exported '+Object.keys(actions).length+' cancellation learnings \u2192 cancel_learnings.json');
    };
    learn.querySelector('#cx-import').onchange=function(e){var f=e.target.files[0];if(!f)return;var r=new FileReader();
      r.onload=function(){try{var o=JSON.parse(r.result);var acts=(o&&o.actions)?o.actions:o;if(acts&&typeof acts==='object'){var cur=cxLoad();cur.actions=Object.assign({},acts,cur.actions||{});cxSave(cur);toast('Imported '+Object.keys(acts).length+' learnings');paint();}else toast('Not a learnings file');}catch(err){toast('Invalid JSON');}};r.readAsText(f);};
    paint();
  },0);

  return v;
};
TITLES.cancellations=['Listen','Cancellation Alerts','Gopher cancellations after accepting \u2014 classify fee / no-fee / excused; iQ learns the patterns.'];

VIEWS.reviews=()=>{
  const v=el('div');
  // Internal post-order ratings between actual users (Gopher Request = requester->gopher; Gopher Go = gopher->requester). Updated daily from Ratings.csv.
  (function(){
    var bd=(M._reports&&M._reports.ratings&&M._reports.ratings.by_direction)||null;
    if(!bd)return;
    function dcard(logo,dirLabel,d){
      var avg=(d&&d.avg)||0,n=(d&&d.n)||0,p5=(d&&d.pct5)||0;
      return '<div class="rv-card" style="display:flex;gap:14px;align-items:center;padding:16px 18px">'+
        '<img src="'+logo+'" alt="" style="height:30px;width:auto;flex:none"/>'+
        '<div style="min-width:0">'+
          '<div style="font-size:11.5px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.3px">'+dirLabel+'</div>'+
          '<div style="font-size:26px;font-weight:800;letter-spacing:-.02em">'+avg.toFixed(2)+' <span style="font-size:13px;color:var(--muted);font-weight:600">/ 5</span></div>'+
          '<div style="margin:2px 0">'+rvStars(avg)+'</div>'+
          '<div style="font-size:11.5px;color:var(--muted)">'+num(n)+' ratings \u00b7 '+p5+'% 5-star</div>'+
        '</div></div>';
    }
    var c=el('div','card');
    c.innerHTML='<div class="card-h"><div><h3>Gopher user ratings</h3><div class="sub">Ratings left after a completed order \u2014 the truest read on two-sided satisfaction. Updated daily from the ratings report.</div></div></div>'+
      '<div class="row" style="grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px;margin-top:4px">'+
        dcard(GLOGO_REQ,'Requesters \u2192 Gophers',bd.req_to_gopher)+
        dcard(GLOGO_GO,'Gophers \u2192 Requesters',bd.gopher_to_req)+
      '</div>';
    v.appendChild(c);
  })();
  // Live App Store data (from fetch_appstore_reviews.py) overrides the Apple cards + feed when present.
  const LIVE=(M._reviews&&M._reviews.apps)?M._reviews.apps:null;
  const ENT=RV_ENT.map(e=>({...e,plats:e.plats.map(p=>{
    if(LIVE&&p.logo==='appstore'&&LIVE[e.name]&&LIVE[e.name].appStore&&LIVE[e.name].appStore.rating!=null){
      const a=LIVE[e.name].appStore; return {...p,rating:a.rating,count:a.count};
    } return p;
  })}));
  let FEED=RV_FEED;
  if(LIVE){
    const live=[];
    Object.keys(LIVE).forEach(name=>((LIVE[name].appStore&&LIVE[name].appStore.recent)||[]).forEach(rv=>live.push({ent:name,plat:'Apple App Store',r:rv.r,title:rv.title,body:rv.body,by:rv.by,date:rv.date,_ts:rv._ts||0})));
    FEED=[...live,...RV_FEED.filter(f=>f.plat!=='Apple App Store')].sort((a,b)=>(b._ts||0)-(a._ts||0)).slice(0,14);
  }
  const all=ENT.flatMap(e=>e.plats);
  const rated=all.filter(p=>p.rating!=null);
  const totalN=all.reduce((a,p)=>a+(p.count||0),0);
  const rn=rated.reduce((a,p)=>a+p.count,0);
  const wRating=rn?rated.reduce((a,p)=>a+p.rating*p.count,0)/rn:0;
  const best=[...rated].sort((a,b)=>b.rating-a.rating)[0],worst=[...rated].sort((a,b)=>a.rating-b.rating)[0];
  const k=el('div','row kpis');
  k.appendChild(kpi('Overall rating',_rvFmt(wRating)+' ★','weighted across app stores',{dot:'#f5a623'}));
  k.appendChild(kpi('Total reviews',num(totalN),'ratings + recommendations',{dot:C.blue}));
  k.appendChild(kpi('Highest-rated',_rvFmt(best.rating)+' ★',best.p,{dot:C.green}));
  k.appendChild(kpi('Needs attention',_rvFmt(worst.rating)+' ★',worst.p,{dot:C.red}));
  v.appendChild(k);
  // per-entity platform cards
  ENT.forEach(e=>{
    const card=el('div','card');
    let h=`<div class="card-h"><div><h3>${e.name}</h3><div class="sub">${e.tag}</div></div></div><div class="row" style="grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px;margin-top:4px">`;
    e.plats.forEach(p=>{
      if(p.pct!=null){
        h+=`<div class="rv-card"><div class="rv-plat">${rvBadge(p)}${rvName(p)}</div><div style="font-size:24px;font-weight:800;letter-spacing:-.02em">${p.pct}% <span style="font-size:13px;color:var(--muted);font-weight:600">recommended</span></div><div style="margin:3px 0;height:15px"></div><div style="font-size:11.5px;color:var(--muted)">${num(p.count)} recommendations</div></div>`;
      } else {
        h+=`<div class="rv-card"><div class="rv-plat">${rvBadge(p)}${rvName(p)}</div><div style="font-size:24px;font-weight:800;letter-spacing:-.02em">${_rvFmt(p.rating)} <span style="font-size:13px;color:var(--muted);font-weight:600">/ 5</span></div><div style="margin:3px 0">${rvStars(p.rating)}</div><div style="font-size:11.5px;color:var(--muted)">${num(p.count)} reviews</div></div>`;
      }
    });
    h+='</div>';card.innerHTML=h;v.appendChild(card);
  });
  // recent reviews feed
  const feed=el('div','card');
  let fh=`<div class="card-h"><div><h3>Recent reviews</h3><div class="sub">${LIVE?'Live from the Apple App Store public feed, newest first.':'Newest across every connected source.'}</div></div></div>`;
  FEED.forEach(rv=>{fh+=`<div class="rv-review"><div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap"><div style="font-weight:700;font-size:13.5px">${rv.title} ${rvStars(rv.r)}</div><div style="font-size:11.5px;color:var(--muted)">${rv.ent} · ${rv.plat} · ${rv.date}</div></div><div style="font-size:13px;color:var(--text);margin:4px 0 3px;line-height:1.5">“${rv.body}”</div><div style="font-size:11.5px;color:var(--muted)">— ${rv.by}</div></div>`;});
  feed.innerHTML=fh;v.appendChild(feed);
  // connectors / honesty
  const src=el('div','card');
  const SRC=[{p:'Apple App Store',logo:'appstore'},{p:'Google Play',logo:'play'},{p:'Facebook',short:'f',color:'#1877f2'}];
  src.innerHTML=`<div class="card-h"><div><h3>Connected review sources</h3><div class="sub">Public listings aggregated per entity.</div></div></div>
    <div style="display:flex;gap:9px;flex-wrap:wrap;margin-top:6px">${SRC.map(s=>`<span class="rv-srcchip">${rvBadge(s)}${s.p}</span>`).join('')}</div>
    <div class="note" style="margin-top:13px"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="M12 8h.01M11 12h1v4h1"/></svg>${LIVE?`Apple App Store ratings and recent reviews are <b>live</b> — pulled from Apple’s public feed (${M._reviews.pulledAt||'recent'}).`:`The store and Facebook figures above are the latest reported ratings. The Apple App Store feed can auto-pull daily (run fetch_appstore_reviews.py); Google Play and Facebook need their console/credentials to refresh automatically.`} The recent-reviews list below is representative sample text. The Facebook badge is a placeholder until you share that logo file.</div>`;
  v.appendChild(src);
  return v;
};
TITLES.reviews=['Listen','Ratings/Reviews','What customers and gophers say about Gopher across the public app stores and social platforms.'];

/* ============ INIT ============ */
window.RANGE='all';
window.GF={range:'all',market:'all',platform:'all'};
window.FINCAT='all';
/* per-view contextual topbar filters — only dimensions that are relevant + working */
const VIEW_FILTERS={
  overview:['range','market','platform'],
  health:['range','market'],
  revenue:['range','market','platform'],
  growth:['range'],
  'p-request':['range','market'],
  financials:['range','bizcat'],
};
const EXPORT_VIEWS={overview:1,health:1,revenue:1,growth:1,'p-request':1,orders:1,people:1};
function renderTopFilters(id){
  const box=$('#filters');if(!box)return;
  const keys=VIEW_FILTERS[id]||[];
  const rangeOpts=`<option value="all">All time</option><option value="12">Last 12 mo</option><option value="6">Last 6 mo</option><option value="3">Last 3 mo</option>`;
  let h='';
  if(keys.includes('range')) h+=`<div class="fl"><label>Range</label><select id="f-range">${rangeOpts}</select></div>`;
  if(keys.includes('market')) h+=`<div class="fl"><label>Market</label><select id="f-market"><option value="all">All markets</option>${(M.order_states_present||[]).map(s=>`<option>${s}</option>`).join('')}</select></div>`;
  if(keys.includes('platform')) h+=`<div class="fl"><label>Platform</label><select id="f-platform"><option value="all">All platforms</option><option>Request</option><option>Go</option><option>Connect</option><option>Deal</option></select></div>`;
  if(keys.includes('bizcat')) h+=`<div class="fl"><label>Business category</label><select id="f-bizcat"><option value="all">All categories</option>${FIN_BUCKETS.map(b=>`<option>${b}</option>`).join('')}</select></div>`;
  if(EXPORT_VIEWS[id]) h+=`<button class="btn" id="btn-export"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 3v12m0 0 4-4m-4 4-4-4M5 21h14"/></svg>Export</button>`;
  box.innerHTML=h;
  const r=$('#f-range');if(r){r.value=window.GF.range;r.onchange=e=>{window.GF.range=e.target.value;window.RANGE=e.target.value;gfRerender();};}
  const mk=$('#f-market');if(mk){mk.value=window.GF.market;mk.onchange=e=>{window.GF.market=e.target.value;gfRerender();};}
  const pf=$('#f-platform');if(pf){pf.value=window.GF.platform;pf.onchange=e=>{window.GF.platform=e.target.value;gfRerender();};}
  const bc=$('#f-bizcat');if(bc){bc.value=window.FINCAT;bc.onchange=e=>{window.FINCAT=e.target.value;gfRerender();};}
  const ex=$('#btn-export');if(ex)ex.onclick=()=>exportCSV(ORD.slice(0,5000).map(o=>({id:o.id,date:dayToStr(o.day),hour:o.h,category:o.cat,status:o.status,market:o.state,device:o.dev,age_restricted:o.ar?'yes':'no',total:o.total,net:o.net.toFixed(2)})),'gopher_orders');
}
function gfRerender(){const cur=document.querySelector('.nav a.active');if(cur)go(cur.dataset.id);}
function setRole(r){
  ROLE=r;
  document.querySelectorAll('#roleSwitch button').forEach(b=>b.classList.toggle('on',b.dataset.role===r));
  const lbl=$('#roleLabel');if(lbl)lbl.textContent=r==='owner'?'Owner':'Admin';
  const cur=document.querySelector('.nav a.active');if(cur)go(cur.dataset.id);
}
function setDataStamp(){
  const md=Math.max(
    (typeof ORD!=='undefined'&&ORD.length)?ORD.reduce((m,o)=>o.day>m?o.day:m,0):0,
    (typeof USR!=='undefined'&&USR.length)?USR.reduce((m,u)=>u.signupDay>m?u.signupDay:m,0):0
  );
  const dataLong = md ? new Date(dayToStr(md)+'T00:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}) : '';
  const usersN = num((typeof USR!=='undefined'?USR.length:0));
  // Precise "last updated" = when this build/refresh actually ran (baked by build.py).
  const bt = (typeof M!=='undefined' && M._built_at) ? new Date(M._built_at) : null;
  if(bt){
    const updLong = bt.toLocaleString(undefined,{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'});
    const updShort = bt.toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
    const ft=$('#dataThrough');if(ft)ft.innerHTML=`Updated <b>${updLong}</b><br>${usersN} users${dataLong?` · data through ${dataLong}`:''}`;
    const st=$('#dataStamp');if(st){
      st.innerHTML=`<span class="lbl">Updated&nbsp;</span>${updShort}`;
      st.classList.remove('stale');
      st.title=`Last refreshed ${updLong}.`+(dataLong?` Latest data in file: ${dataLong}.`:'');
    }
    return;
  }
  // Fallback (older build with no _built_at): keep the original data-through behavior.
  if(!md)return;
  const d=new Date(dayToStr(md)+'T00:00:00');
  const long=dataLong, shortd=d.toLocaleDateString(undefined,{month:'short',day:'numeric'});
  const today=new Date();today.setHours(0,0,0,0);
  const stale=d.getTime()<today.getTime();
  const ft=$('#dataThrough');if(ft)ft.innerHTML=`Data through <b>${long}</b><br>${usersN} users in this build`;
  const st=$('#dataStamp');if(st){
    st.innerHTML=`<span class="lbl">Data through&nbsp;</span>${shortd}`;
    st.classList.toggle('stale',stale);
    st.title=stale
      ?`This file's latest data is ${long} — older than today. You may be viewing an older build; re-open the file your last update wrote to Dashboard/output/.`
      :`Latest data in this file: ${long}`;
  }
}
function init(){
  PRICING=seedPricing(); loadAudit(); seedPromos(); gbfbInit(); iafbInit(); cxfbInit();
  const bd=$('#brand');if(bd&&M._brand&&M._brand.gopherMark)bd.innerHTML=`<div class="logo"><img src="${M._brand.gopherMark}" alt="Gopher"></div><div><div class="word"><b>gopher</b>·HQ</div><div class="sub">Operating Dashboard</div></div>`;
  buildNav();
  setupMobileNav();
  setDataStamp();
  updateAlertBadge();
  document.querySelectorAll('#roleSwitch button').forEach(b=>b.onclick=()=>setRole(b.dataset.role));
  const start=(location.hash||'#snapshot').slice(1);
  go(VIEWS[start]?start:'snapshot');
}
init();
